{
  "title": "Discussion on tax filing, domain purchase, product viability, and security concerns",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing process",
      "claims": [
        {
          "text": "Procedures for tax declarations require careful column checks; errors can lead to large penalties.",
          "evidence": [1, 8]
        },
        {
          "text": "The procedure can be completed in roughly an hour using Excel, about a day per month.",
          "evidence": [5, 6]
        },
        {
          "text": "The FOP calculator works only with hryvnia, requiring conversion using daily exchange rates.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase considerations",
      "claims": [
        {
          "text": "No domain has been purchased yet.",
          "evidence": [2]
        },
        {
          "text": "Purchasing the calculator is expected to generate funds for buying a domain.",
          "evidence": [4]
        },
        {
          "text": "Some participants doubt buying a domain is worthwhile.",
          "evidence": [9]
        }
      ]
    },
    {
      "id": "product-viability",
      "title": "Product viability and market prospects",
      "claims": [
        {
          "text": "Web platform is seen as less profitable than mobile apps, with poor SEO and low user retention.",
          "evidence": [11]
        },
        {
          "text": "Fast delivery (<1 week) and using a cross‑platform stack (Flutter) are suggested for quick launch.",
          "evidence": [12]
        },
        {
          "text": "Earning money from the product is considered unlikely, with expectation of no sales for months.",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience now has fewer technical/managerial posts.",
          "evidence": [18]
        },
        {
          "text": "Project viability depends on at least ten users willing to pay 299 UAH.",
          "evidence": [20]
        }
      ]
    },
    {
      "id": "technical-stack",
      "title": "Technical stack considerations",
      "claims": [
        {
          "text": "Flutter is recommended as a quick cross‑platform development framework.",
          "evidence": [12]
        }
      ]
    },
    {
      "id": "security-concerns",
      "title": "Security and password handling concerns",
      "claims": [
        {
          "text": "The app stores the promo code password in local storage, making it easy to discover.",
          "evidence": [20, 23, 28]
        },
        {
          "text": "The app is marketed as a local‑first app with USD/UAH rates fetched every 5 minutes, but core functionality is bundled.",
          "evidence": [29]
        },
        {
          "text": "There are accusations that the project is a low‑quality or scam \"vibe code\".",
          "evidence": [30, 32, 33, 34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "How long does the entire tax filing procedure take? Is it about an hour with Excel?",
      "evidence": [5]
    },
    {
      "text": "What is the source code and can the stored password be found by searching?",
      "evidence": [21]
    }
  ]
}
